   report.cases.push({name:mobile?'cache-mobile-no-prefetch':'cache-desktop-eight-limit',status:'pass',instrumentation:'Decode wrapper observes original promise without replacement; cache getter read-only; 250ms warm observation window per selection',memory_claim:'RGBA surface estimates only, not measured process/GPU memory',ids,trace,requests,performance,max_observed_entries:Math.max(...trace.map(t=>t.cache.size)),eviction_limit_observed:trace.some(t=>t.cache.size===8),limit_observation:trace.some(t=>t.cache.size===8)?'OBSERVED_AT_EIGHT':'NOT_OBSERVED'});await closePage(page);
